<script setup lang="ts">
import { useFinancialInvestmentsService } from '~/modulos/erp/financial-investments/financial-investments.service'
import { useBankAccounts } from '~/modulos/erp/bank-accounts/composables/useBankAccounts'
import { useBankConcepts } from '~/modulos/erp/bank-concepts/composable/useBankConcepts'
import { useBankAccountsService } from '~/modulos/erp/bank-accounts/service/bank-accounts.service'
definePageMeta({ middleware: ['auth'] })
const route = useRoute(); const service = useFinancialInvestmentsService(); const toast = useToast()
const { bankAccounts, init: initBanks } = useBankAccounts()
const bankConcepts = useBankConcepts()
const row = ref<any>(null); const loading = ref(true); const valuationOpen = ref(false); const settleOpen = ref(false); const redeemOpen = ref(false); const saving = ref(false)
const suggestionLoading = ref(false); const bankAccountService = useBankAccountsService()
const today = () => new Date().toISOString().slice(0, 10)
const valuation = reactive({ valuation_date: today(), unit_value: null as number | null, notes: '' })
const settlement = reactive<any>({ mode: 'CREDIT_ALL', date: today(), actual_amount: null, bank_account_id: '', new_annual_nominal_rate: null, new_maturity_date: '', reference: '', notes: '', charges: [] })
const redemption = reactive<any>({ date: today(), units: null, credited_amount: null, bank_account_id: '', reference: '', notes: '', charges: [] })
const money = (value: any, currency = row.value?.currency_code || 'ARS') => new Intl.NumberFormat('es-AR', { style: 'currency', currency }).format(Number(value || 0))
const dateLabel = (value?: string) => value ? new Date(value).toLocaleDateString('es-AR', { timeZone: 'UTC' }) : '—'
const bankOptions = computed(() => bankAccounts.value.filter((b: any) => b.active && b.currency_code === row.value?.currency_code).map((b: any) => ({ label: `${b.bank_name} · ${b.name}`, value: b.id })))
const settlementConceptOptions = computed(() => bankConcepts.activeConcepts.value.filter((c: any) => c.available_settlements).map((c: any) => ({ label: `${c.code} · ${c.name}`, value: c.id })))
const settlementCharges = computed(() => settlement.charges.reduce((sum: number, charge: any) => sum + Number(charge.amount || 0), 0))
const settlementNet = computed(() => Number(settlement.actual_amount || 0) - settlementCharges.value)
const addSettlementCharge = () => settlement.charges.push({ concept_id: '', amount: null })
const redemptionCharges = computed(() => redemption.charges.reduce((sum: number, charge: any) => sum + Number(charge.amount || 0), 0))
const loadInvestmentSuggestions = async (target: any, trigger: 'INVESTMENT_REDEMPTION' | 'FIXED_TERM_EARLY_CANCEL', amount: number) => {
  if (!target.bank_account_id || !amount) return
  suggestionLoading.value = true
  try {
    const suggestions = await bankAccountService.getSuggestedCharges(target.bank_account_id, { trigger, amount, date: target.date, currency_code: row.value.currency_code })
    target.charges = [...target.charges.filter((charge:any) => !charge.suggested), ...suggestions.map(s => ({ concept_id: s.bank_concept_id, amount: s.total_amount, suggested: true, rule_name: s.rule_name }))]
  } catch (e:any) { toast.add({ title: 'No se pudieron calcular los cargos sugeridos', description: e?.data?.message, color: 'warning' }) }
  finally { suggestionLoading.value = false }
}
const typeLabel = computed(() => row.value?.type === 'FIXED_TERM' ? 'Plazo fijo' : row.value?.type === 'INVESTMENT_FUND' ? 'Fondo / FIMA' : 'Otra inversión')
const active = computed(() => ['ACTIVE', 'MATURED_PENDING_SETTLEMENT'].includes(row.value?.display_status || row.value?.status))
const isBeforeMaturity = computed(() => Boolean(row.value?.maturity_date && new Date(`${today()}T00:00:00Z`) < new Date(`${String(row.value.maturity_date).slice(0, 10)}T00:00:00Z`)))
const canSettleFixedTerm = computed(() => {
  if (!active.value || row.value?.type !== 'FIXED_TERM' || !row.value?.maturity_date) return false
  return !isBeforeMaturity.value || Boolean(row.value.can_early_cancel)
})
const openFixedTermSettlement = async () => {
  settlement.mode = 'CREDIT_ALL'
  settlement.date = today()
  settlement.actual_amount = Number(isBeforeMaturity.value ? row.value.early_cancel_value : row.value.expected_final_amount)
  settlement.charges = []
  await loadInvestmentSuggestions(settlement, isBeforeMaturity.value ? 'FIXED_TERM_EARLY_CANCEL' : 'INVESTMENT_REDEMPTION', Number(settlement.actual_amount || 0))
  settleOpen.value = true
}
const openRedemption = async () => { redemption.charges = []; redemption.credited_amount = Number(row.value.current_value || 0); await loadInvestmentSuggestions(redemption, 'INVESTMENT_REDEMPTION', Number(redemption.credited_amount)); redeemOpen.value = true }
const load = async () => { loading.value = true; try { row.value = await service.findOne(String(route.params.id)); settlement.actual_amount = Number(row.value.expected_final_amount || row.value.current_value); settlement.bank_account_id = row.value.destination_bank_account_id || row.value.source_bank_account_id; redemption.bank_account_id = row.value.destination_bank_account_id || row.value.source_bank_account_id } finally { loading.value = false } }
const saveValuation = async () => { saving.value = true; try { row.value = await service.addValuation(row.value.id, valuation); valuationOpen.value = false; toast.add({ title: 'Valuación actualizada', color: 'success' }) } catch(e:any){ toast.add({ title:'No se pudo actualizar', description:e?.data?.message, color:'error' }) } finally { saving.value=false } }
const settle = async () => { saving.value=true; try { const payload = { ...settlement, charges: settlement.charges.filter((charge:any) => charge.concept_id && Number(charge.amount) > 0) }; row.value=await service.settle(row.value.id, payload); settleOpen.value=false; toast.add({ title: settlement.mode === 'CREDIT_ALL' ? 'Plazo fijo acreditado' : 'Plazo fijo renovado', color:'success' }) } catch(e:any){ toast.add({ title:'No se pudo liquidar', description:e?.data?.message, color:'error' }) } finally { saving.value=false } }
const redeem = async () => { saving.value=true; try { const payload = { ...redemption, charges: redemption.charges.filter((charge:any) => charge.concept_id && Number(charge.amount) > 0) }; row.value=await service.redeem(row.value.id, payload); redeemOpen.value=false; toast.add({ title:'Rescate registrado', color:'success' }) } catch(e:any){ toast.add({ title:'No se pudo rescatar', description:e?.data?.message, color:'error' }) } finally { saving.value=false } }
onMounted(async()=>{ await Promise.all([initBanks(), bankConcepts.init()]); await load() })
</script>

<template><UPage class="space-y-5">
  <AppPageHeader :title="row?.name || 'Inversión'" :description="row ? `${typeLabel} · ${row.institution_name || 'Sin institución'}` : 'Cargando inversión'">
    <template #links><UButton label="Volver" icon="i-lucide-arrow-left" variant="ghost" to="/erp/treasury/investments"/><UButton v-if="active && row?.type === 'INVESTMENT_FUND'" label="Nueva valuación" icon="i-lucide-chart-line" variant="outline" @click="valuationOpen=true"/><UButton v-if="active && row?.type === 'INVESTMENT_FUND'" label="Registrar rescate" icon="i-lucide-circle-dollar-sign" @click="openRedemption"/><UButton v-if="canSettleFixedTerm" :label="isBeforeMaturity ? 'Precancelar inversión' : 'Liquidar o renovar'" icon="i-lucide-landmark" @click="openFixedTermSettlement"/></template>
  </AppPageHeader>
  <div v-if="loading" class="grid gap-4 md:grid-cols-3"><USkeleton v-for="n in 6" :key="n" class="h-28"/></div>
  <template v-else-if="row">
    <UAlert v-if="active && row.type === 'FIXED_TERM' && !canSettleFixedTerm" icon="i-lucide-calendar-clock" color="info" variant="subtle" title="Plazo fijo vigente" :description="row.liquidity_type === 'PRE_CANCELABLE' ? `Podrás precancelarlo desde el ${dateLabel(row.early_cancel_available_from)} o liquidarlo normalmente el ${dateLabel(row.maturity_date)}.` : `Podrás liquidarlo o renovarlo a partir del ${dateLabel(row.maturity_date)}. Mientras tanto, el valor actual seguirá calculándose diariamente.`" />
    <UAlert v-if="active && row.type === 'FIXED_TERM' && row.can_early_cancel" icon="i-lucide-unlock" color="warning" variant="subtle" title="Prec cancelación disponible" :description="`Si retirás hoy, el importe estimado es ${money(row.early_cancel_value)} usando la TNA de precancelación del ${Number(row.early_cancel_annual_rate || 0).toLocaleString('es-AR')}%. Podrás corregirlo con el importe informado por el banco.`" />
    <div class="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><UCard><p class="text-xs text-muted">Capital invertido</p><p class="mt-1 text-xl font-semibold">{{ money(row.capital_amount) }}</p></UCard><UCard><p class="text-xs text-muted">Valor actual</p><p class="mt-1 text-xl font-semibold">{{ money(row.current_value) }}</p></UCard><UCard><p class="text-xs text-muted">Rendimiento devengado</p><p class="mt-1 text-xl font-semibold text-success">{{ money(row.accrued_return) }}</p></UCard><UCard><p class="text-xs text-muted">Rendimiento al vencimiento</p><p class="mt-1 text-xl font-semibold">{{ row.projected_return == null ? 'Según valuación' : money(row.projected_return) }}</p></UCard></div>
    <UCard><div class="grid gap-5 sm:grid-cols-2 lg:grid-cols-4"><div><p class="text-xs text-muted">Cuenta de origen</p><strong>{{ row.source_bank_account?.bank_name }} · {{ row.source_bank_account?.name }}</strong></div><div><p class="text-xs text-muted">Constitución</p><strong>{{ dateLabel(row.start_date) }}</strong></div><div v-if="row.type==='FIXED_TERM'"><p class="text-xs text-muted">TNA / base</p><strong>{{ Number(row.annual_nominal_rate).toLocaleString('es-AR') }}% · {{ row.day_count_basis }} días</strong></div><div v-if="row.type==='FIXED_TERM'"><p class="text-xs text-muted">Vencimiento</p><strong>{{ dateLabel(row.maturity_date) }} · {{ row.days_remaining }} días</strong></div><div v-if="row.type==='INVESTMENT_FUND'"><p class="text-xs text-muted">Cuotapartes</p><strong>{{ Number(row.units).toLocaleString('es-AR',{maximumFractionDigits:8}) }}</strong></div><div v-if="row.type==='INVESTMENT_FUND'"><p class="text-xs text-muted">Valor de cuotaparte</p><strong>{{ Number(row.current_unit_value).toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:8}) }}</strong></div></div></UCard>
    <div class="grid gap-5 xl:grid-cols-2"><UCard><template #header><h2 class="font-semibold">Movimientos de la inversión</h2></template><div class="divide-y divide-default"><div v-for="item in row.transactions" :key="item.id" class="flex justify-between py-3"><div><strong>{{ item.type }}</strong><p class="text-sm text-muted">{{ dateLabel(item.date) }} · {{ item.notes || item.reference || 'Sin observaciones' }}</p></div><strong>{{ money(item.amount) }}</strong></div><p v-if="!row.transactions?.length" class="text-muted">Sin movimientos.</p></div></UCard><UCard><template #header><h2 class="font-semibold">Historial de valuaciones</h2></template><div class="divide-y divide-default"><div v-for="item in row.valuations" :key="item.id" class="flex justify-between py-3"><div><strong>{{ dateLabel(item.valuation_date) }}</strong><p class="text-sm text-muted">Cuotaparte {{ Number(item.unit_value).toLocaleString('es-AR',{maximumFractionDigits:8}) }}</p></div><div class="text-right"><strong>{{ money(item.total_value) }}</strong><p class="text-sm text-success">{{ money(item.unrealized_return) }}</p></div></div><p v-if="!row.valuations?.length" class="text-muted">El plazo fijo se calcula diariamente sin generar registros.</p></div></UCard></div>
  </template>

  <UModal v-model:open="valuationOpen" title="Actualizar valuación del fondo" :ui="{content:'sm:max-w-xl'}"><template #body><div class="space-y-4"><UFormField label="Fecha" required><UInput v-model="valuation.valuation_date" type="date" class="w-full"/></UFormField><UFormField label="Valor de cuotaparte" required><UInput v-model.number="valuation.unit_value" type="number" step="0.00000001" class="w-full"/></UFormField><UFormField label="Notas"><UTextarea v-model="valuation.notes" class="w-full"/></UFormField><div class="flex justify-end gap-2"><UButton label="Cancelar" variant="ghost" @click="valuationOpen=false"/><UButton label="Guardar valuación" :loading="saving" :disabled="!valuation.unit_value" @click="saveValuation"/></div></div></template></UModal>
  <UModal v-model:open="settleOpen" :title="isBeforeMaturity ? 'Prec cancelar plazo fijo' : 'Liquidar o renovar plazo fijo'" :ui="{content:'sm:max-w-3xl'}"><template #body><div class="space-y-4"><UAlert :title="isBeforeMaturity ? 'Rescate anticipado' : 'Confirmación bancaria'" :description="isBeforeMaturity ? 'El importe sugerido incluye capital más el interés acumulado hasta hoy con la TNA de precancelación, no el interés total al vencimiento.' : 'El saldo del banco se modificará únicamente por el importe que realmente se acredite.'" color="info" variant="subtle"/><UFormField v-if="!isBeforeMaturity" label="Acción" required><USelect v-model="settlement.mode" :items="[{label:'Acreditar capital e intereses',value:'CREDIT_ALL'},{label:'Renovar capital y acreditar intereses',value:'RENEW_CAPITAL'},{label:'Renovar capital e intereses',value:'RENEW_ALL'}]" value-key="value" class="w-full"/></UFormField><div class="grid gap-4 sm:grid-cols-2"><UFormField label="Fecha real"><UInput v-model="settlement.date" type="date" :min="isBeforeMaturity ? row.early_cancel_available_from?.slice(0,10) : row.maturity_date?.slice(0,10)" class="w-full"/></UFormField><UFormField :label="isBeforeMaturity ? 'Importe bruto del rescate anticipado' : 'Importe bruto al vencimiento'"><UInput v-model.number="settlement.actual_amount" type="number" step="0.01" class="w-full"/></UFormField><UFormField v-if="settlement.mode !== 'RENEW_ALL'" label="Cuenta de acreditación"><USelectMenu v-model="settlement.bank_account_id" :items="bankOptions" value-key="value" class="w-full"/></UFormField><template v-if="!isBeforeMaturity && settlement.mode !== 'CREDIT_ALL'"><UFormField label="Nueva TNA %"><UInput v-model.number="settlement.new_annual_nominal_rate" type="number" step="0.0001" class="w-full"/></UFormField><UFormField label="Nuevo vencimiento" required><UInput v-model="settlement.new_maturity_date" type="date" class="w-full"/></UFormField></template></div><div v-if="settlement.mode !== 'RENEW_ALL'" class="rounded-lg border border-default p-4 space-y-3"><div class="flex items-center justify-between"><div><h3 class="font-medium">Gastos y retenciones bancarias</h3><p class="text-sm text-muted">Se registran con los conceptos habilitados para liquidaciones.</p></div><UButton label="Agregar concepto" icon="i-lucide-plus" size="sm" variant="outline" @click="addSettlementCharge"/></div><div v-for="(charge,index) in settlement.charges" :key="index" class="grid gap-2 sm:grid-cols-[1fr_10rem_auto]"><USelectMenu v-model="charge.concept_id" :items="settlementConceptOptions" value-key="value" placeholder="Concepto bancario" class="w-full"/><UInput v-model.number="charge.amount" type="number" step="0.01" placeholder="Importe" class="w-full"/><UButton icon="i-lucide-trash-2" color="error" variant="ghost" @click="settlement.charges.splice(index,1)"/></div><div class="flex justify-between border-t border-default pt-3 text-sm"><span>Bruto {{ money(settlement.actual_amount) }} · descuentos {{ money(settlementCharges) }}</span><strong>Neto bancario {{ money(settlementNet) }}</strong></div></div><UFormField label="Observaciones"><UTextarea v-model="settlement.notes" class="w-full"/></UFormField><div class="flex justify-end gap-2"><UButton label="Cancelar" variant="ghost" @click="settleOpen=false"/><UButton :label="isBeforeMaturity ? 'Confirmar precancelación' : 'Confirmar'" :loading="saving" @click="settle"/></div></div></template></UModal>
  <UModal v-model:open="redeemOpen" title="Registrar rescate del fondo" :ui="{content:'sm:max-w-3xl'}"><template #body><div class="space-y-4"><div class="grid gap-4 sm:grid-cols-2"><UFormField label="Fecha"><UInput v-model="redemption.date" type="date" class="w-full"/></UFormField><UFormField label="Cuenta de acreditación"><USelectMenu v-model="redemption.bank_account_id" :items="bankOptions" value-key="value" class="w-full"/></UFormField><UFormField label="Cuotapartes rescatadas"><UInput v-model.number="redemption.units" type="number" step="0.00000001" class="w-full"/></UFormField><UFormField label="Importe bruto del rescate"><UInput v-model.number="redemption.credited_amount" type="number" step="0.01" class="w-full"/></UFormField></div><div class="rounded-lg border border-default p-4 space-y-3"><div class="flex justify-between"><div><h3 class="font-medium">Gastos y retenciones</h3><p class="text-sm text-muted">Se descuentan del importe bruto al acreditar.</p></div><UButton label="Agregar concepto" icon="i-lucide-plus" size="sm" variant="outline" @click="redemption.charges.push({concept_id:'',amount:null})"/></div><div v-for="(charge,index) in redemption.charges" :key="index" class="grid gap-2 sm:grid-cols-[1fr_10rem_auto]"><USelectMenu v-model="charge.concept_id" :items="settlementConceptOptions" value-key="value" class="w-full"/><UInput v-model.number="charge.amount" type="number" step="0.01" class="w-full"/><UButton icon="i-lucide-trash-2" color="error" variant="ghost" @click="redemption.charges.splice(index,1)"/></div><div class="flex justify-between border-t border-default pt-3 text-sm"><span>Descuentos {{ money(redemptionCharges) }}</span><strong>Neto bancario {{ money(Number(redemption.credited_amount || 0) - redemptionCharges) }}</strong></div></div><UFormField label="Observaciones"><UTextarea v-model="redemption.notes" class="w-full"/></UFormField><div class="flex justify-end gap-2"><UButton label="Cancelar" variant="ghost" @click="redeemOpen=false"/><UButton label="Confirmar rescate" :loading="saving" :disabled="!redemption.units || redemption.credited_amount == null || !redemption.bank_account_id" @click="redeem"/></div></div></template></UModal>
</UPage></template>
